"""Small payment API with isolated application state per factory call."""

from fastapi import FastAPI, HTTPException, Header, Request
from fastapi.responses import JSONResponse
from pydantic import BaseModel, Field, validator

from ledger import Ledger
from service import PaymentService


class RefundRequest(BaseModel):
    amount: int = Field(..., gt=0, description="Refund amount in paise, must be positive integer")

    @validator('amount')
    def amount_positive(cls, v):
        if v <= 0:
            raise ValueError('amount must be positive')
        return v


def create_app():
    app = FastAPI()
    ledger = Ledger()
    service = PaymentService(ledger)

    @app.get("/payments/{payment_id}")
    def get_payment(payment_id: str):
        try:
            return service.get_payment(payment_id)
        except KeyError:
            raise HTTPException(404, "Payment not found") from None

    @app.post("/payments/{payment_id}/refunds")
    async def create_refund(
        payment_id: str,
        request: Request,
        refund: RefundRequest,
        idempotency_key: str = Header(..., alias="Idempotency-Key"),
    ):
        # Header validation per spec
        if not (1 <= len(idempotency_key) <= 64):
            raise HTTPException(422, "Invalid Idempotency-Key length")
        if not all(c.isalnum() or c in "_-" for c in idempotency_key):
            raise HTTPException(422, "Invalid Idempotency-Key characters")
        try:
            result = service.create_refund(
                payment_id=payment_id,
                amount=refund.amount,
                idempotency_key=idempotency_key,
            )
        except KeyError:
            raise HTTPException(404, "Payment not found") from None
        except ValueError as ve:
            # business rule conflict
            raise HTTPException(409, str(ve)) from None
        except service.IdempotencyConflict as ic:
            # key used for different payment/amount
            raise HTTPException(409, str(ic)) from None
        # Determine status code based on whether this is a replay
        status_code = 200 if result["_replay"] else 201
        # Remove internal flag before returning
        result.pop("_replay", None)
        return JSONResponse(content=result, status_code=status_code)

    return app

"""In-memory ledger for a controlled local exercise, not a payment gateway."""

from threading import RLock
from typing import Dict, Any


class Ledger:
    def __init__(self):
        self.lock = RLock()
        self.payments: Dict[str, Dict[str, Any]] = {
            "p1": {"id": "p1", "amount": 1000, "refunded": 0, "status": "captured"},
            "p2": {"id": "p2", "amount": 500, "refunded": 0, "status": "captured"},
            "p3": {"id": "p3", "amount": 700, "refunded": 0, "status": "cancelled"},
        }
        self.refunds: Dict[str, Dict[str, Any]] = {}
        # idempotency_key -> (payment_id, amount, response_dict)
        self.idempotency_keys: Dict[str, Dict[str, Any]] = {}

"""Business logic; transport concerns belong in api.py."""

from ledger import Ledger
from typing import Dict, Any


class IdempotencyConflict(Exception):
    pass


class PaymentService:
    def __init__(self, ledger: Ledger):
        self.ledger = ledger

    def get_payment(self, payment_id: str) -> dict:
        with self.ledger.lock:
            if payment_id not in self.ledger.payments:
                raise KeyError(payment_id)
            return dict(self.ledger.payments[payment_id])

    def _record_idempotency(self, key: str, payment_id: str, amount: int, response: Dict[str, Any]):
        self.ledger.idempotency_keys[key] = {
            "payment_id": payment_id,
            "amount": amount,
            "response": response,
        }

    def _check_idempotency(self, key: str, payment_id: str, amount: int):
        entry = self.ledger.idempotency_keys.get(key)
        if entry is None:
            return None
        if entry["payment_id"] != payment_id or entry["amount"] != amount:
            raise IdempotencyConflict("Idempotency key used with different payment or amount")
        # Return stored response for replay
        return entry["response"].copy()

    def create_refund(self, payment_id: str, amount: int, idempotency_key: str) -> Dict[str, Any]:
        with self.ledger.lock:
            # Idempotency replay check first
            replay_response = self._check_idempotency(idempotency_key, payment_id, amount)
            if replay_response is not None:
                replay_response["_replay"] = True
                return replay_response

            # Validate payment existence
            payment = self.ledger.payments.get(payment_id)
            if payment is None:
                raise KeyError(payment_id)

            if payment["status"] != "captured":
                raise ValueError("Cannot refund a non‑captured payment")

            remaining = payment["amount"] - payment["refunded"]
            if amount > remaining:
                raise ValueError("Refund amount exceeds remaining captured amount")

            # Perform refund mutation
            payment["refunded"] += amount
            if payment["refunded"] == payment["amount"]:
                payment["status"] = "refunded"
                status = "refunded"
            else:
                status = "partially_refunded"

            response = {
                "payment_id": payment_id,
                "amount": amount,
                "refunded_total": payment["refunded"],
                "status": status,
            }
            # Record idempotency for future replays
            self._record_idempotency(idempotency_key, payment_id, amount, response)
            response["_replay"] = False
            return response

